#include "../../core/runtime/runtime.h"

/* Platform entropy headers live here (NOT in the shared runtime.h, which
 * every TU includes): <sys/random.h> is absent from older cross-compile
 * sysroots, so on Linux we skip it entirely and call getrandom(2) via
 * syscall(SYS_getrandom). macOS uses the Security framework. */
#if defined(__linux__)
#  include <sys/syscall.h>          /* SYS_getrandom */
#elif defined(__APPLE__)
#  include <Security/Security.h>    /* SecRandomCopyBytes, kSecRandomDefault */
#endif

/* Generated by Phase 2 #06.5 T8: kernel CSPRNG-backed random bytes. */

/* ── std::rand ────────────────────────────────────────────────────────
 *
 * Three free fns: random_bytes(n), random_u64(), random_fill(&var buf).
 * All paths route to the OS kernel CSPRNG — no userspace state, no
 * seedable PRNG. Backend selection is compile-time:
 *
 *   __linux__   -> syscall(SYS_getrandom, ...), /dev/urandom fallback
 *   __APPLE__   -> SecRandomCopyBytes(...)   [<Security/Security.h>]
 *   else        -> /dev/urandom open + read-loop
 *
 * On Linux we issue the getrandom(2) syscall directly rather than via the
 * glibc wrapper in <sys/random.h> (glibc >= 2.25), so the runtime still
 * builds against older cross-compile sysroots; if the syscall is missing
 * (pre-3.17 kernel) or blocked we fall back to /dev/urandom. The macOS
 * `Security` framework header is included locally above. The
 * `-framework Security` link flag is added in
 * codegen/object.rs::linker_args under cfg!(target_os = "macos").
 *
 * Error model: hard CSPRNG failure → IoError.Other(msg) (random_bytes
 * / random_fill) or ruxen_panic (random_u64 — the caller is presumed
 * to want an unconditional number). Negative n → IoError.InvalidInput.
 * Zero n → Ok(empty) without invoking the kernel.
 */

/* Fill `out` with `len` bytes from /dev/urandom. Returns 0 on success,
 * -1 on hard failure (errno preserved). open(2) surfaces ENOENT if the
 * device node is missing so the caller's IoError classifier picks
 * NotFound. Used as the Linux getrandom(2) fallback and the generic
 * Unix path. */
static int ruxen_rand_fill_urandom(unsigned char *out, size_t len) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    size_t off = 0;
    while (off < len) {
        ssize_t got = read(fd, out + off, len - off);
        if (got < 0) {
            if (errno == EINTR) continue;
            int saved = errno;
            (void)close(fd);
            errno = saved;
            return -1;
        }
        if (got == 0) {
            /* /dev/urandom should never EOF; treat as hard failure. */
            (void)close(fd);
            errno = EIO;
            return -1;
        }
        off += (size_t)got;
    }
    (void)close(fd);
    return 0;
}

/* Fill `out` with `len` bytes from the kernel CSPRNG. Returns 0 on
 * success, -1 on hard failure (caller maps to IoError.Other). The
 * `errno` left in place mirrors the syscall's last failure. */
static int ruxen_rand_fill_raw(unsigned char *out, size_t len) {
    if (len == 0) return 0;

#if defined(__linux__)
    /* getrandom(2) via raw syscall — avoids <sys/random.h> (glibc >= 2.25),
     * which is missing on older cross-compile sysroots. Fall back to
     * /dev/urandom when the syscall is unavailable (pre-3.17 kernel ->
     * ENOSYS) or blocked by a sandbox/seccomp policy (EPERM). */
    size_t off = 0;
    while (off < len) {
#  if defined(SYS_getrandom)
        ssize_t got = syscall(SYS_getrandom, out + off, len - off, 0);
#  else
        ssize_t got = -1;
        errno = ENOSYS;
#  endif
        if (got < 0) {
            if (errno == EINTR) continue;
            if (errno == ENOSYS || errno == EPERM)
                return ruxen_rand_fill_urandom(out, len);
            return -1;
        }
        off += (size_t)got;
    }
    return 0;
#elif defined(__APPLE__)
    /* SecRandomCopyBytes returns errSecSuccess (0) on success. The
     * function fills the entire buffer or fails — no partial-fill
     * contract, so a single call is sufficient. */
    if (SecRandomCopyBytes(kSecRandomDefault, len, out) != errSecSuccess) {
        /* SecRandomCopyBytes doesn't set errno; synthesise EIO so the
         * `from_errno` classifier maps to a non-InvalidInput variant
         * (it falls through to Other for unknown errnos). */
        errno = EIO;
        return -1;
    }
    return 0;
#else
    return ruxen_rand_fill_urandom(out, len);
#endif
}

/* `random_bytes(n: Int) -> Result[Array[U8], IoError]`. n<0 →
 * InvalidInput; n==0 → Ok(empty Vec) without invoking the kernel;
 * n>0 → fresh RuxenVec with each byte pushed as an int64 slot
 * (matching the Array[Int]/Array[U8] carrier convention used by
 * File.read / TcpStream.read). On CSPRNG hard failure the partial
 * Vec is freed before surfacing Err. */
void *ruxen_rand_random_bytes(int64_t n) {
    if (n < 0) {
        return ruxen_result_err_value(
            (int64_t)ruxen_io_error_unit(RUXEN_IO_ERROR_INVALID_INPUT));
    }
    RuxenVec *v = ruxen_vec_new();
    if (n == 0) {
        return ruxen_result_ok_value((int64_t)v);
    }
    /* Stage into a heap buffer so we don't blow the stack on a large n
     * — getrandom's 256-byte single-call limit is per-syscall, not per
     * buffer, and the read-loop above handles partial fills. */
    size_t len = (size_t)n;
    unsigned char *stage = (unsigned char *)malloc(len);
    if (!stage) ruxen_panic("out of memory");
    if (ruxen_rand_fill_raw(stage, len) != 0) {
        int saved = errno;
        free(stage);
        ruxen_dealloc(v);
        return ruxen_io_error_from_errno(saved);
    }
    for (size_t i = 0; i < len; i++) {
        ruxen_vec_push(v, (int64_t)stage[i]);
    }
    free(stage);
    return ruxen_result_ok_value((int64_t)v);
}

/* `random_u64() -> Int`. The int64 storage carries the 64-bit CSPRNG
 * sample verbatim — callers that want a signed interpretation can
 * read as-is; unsigned consumers reinterpret the bit pattern. On
 * hard CSPRNG failure we panic rather than return a Result so the
 * call site stays a bare expression. */
int64_t ruxen_rand_random_u64(void) {
    uint64_t out = 0;
    if (ruxen_rand_fill_raw((unsigned char *)&out, sizeof out) != 0) {
        ruxen_panic("random_u64: kernel CSPRNG hard failure");
    }
    return (int64_t)out;
}

/* `random_fill(buf: &var Array[U8]) -> Result[(), IoError]`. Overwrites
 * every existing slot of `buf` with one random byte each; preserves
 * `buf.len`. Empty buf → Ok(()) immediately. */
void *ruxen_rand_random_fill(RuxenVec *buf) {
    if (!buf) {
        return ruxen_result_err_value(
            (int64_t)ruxen_io_error_unit(RUXEN_IO_ERROR_INVALID_INPUT));
    }
    size_t len = (size_t)buf->len;
    if (len == 0) {
        return ruxen_result_ok_value(0);
    }
    unsigned char *stage = (unsigned char *)malloc(len);
    if (!stage) ruxen_panic("out of memory");
    if (ruxen_rand_fill_raw(stage, len) != 0) {
        int saved = errno;
        free(stage);
        return ruxen_io_error_from_errno(saved);
    }
    for (size_t i = 0; i < len; i++) {
        buf->data[i] = (int64_t)stage[i];
    }
    free(stage);
    return ruxen_result_ok_value(0);
}
